'''
Custom app-packaged CherryPy endpoint handler

This module enables Splunk apps to package their own splunkweb HTTP handlers
that can provide custom functionality.

This uses Python's import hooks to dynamically locate and import python modules
from apps.  This looks specifically for files that match the pattern:

    $SPLUNK_HOME/etc/apps/.../appserver/controllers/*.py

and contain a class that inherits from:

    splunk.appserver.mrsparkle.controllers.BaseController

The second part of this file is the actual CherryPy mount point that routes the
requests over to the registered app-packaged controllers.

See: http://www.python.org/dev/peps/pep-0302/
'''

from builtins import object
import importlib.abc
import importlib.util
import types
import inspect
import logging
import os
import re
import sys
from subprocess import PIPE
from splunk.clilib.cli_common import getMergedConf

import cherrypy
import splunk

from splunk.appserver.mrsparkle.controllers import BaseController
from splunk.appserver.mrsparkle.lib.decorators import expose_page
from splunk.appserver.mrsparkle.lib.routes import route
from splunk.appserver.mrsparkle.lib.util import get_apps_dir
from splunk.appserver.mrsparkle.lib.util import Popen
import splunk.appserver.mrsparkle.controllers as controllers
import splunk.entity as en

logger = logging.getLogger('splunk.appserver.mrsparkle.controllers.custom')


# define the python package space in which to house custom controllers
# thay may be packaged with apps
VIRTUAL_PACKAGE_NAME = 'splunk.appserver.mrsparkle.custom_controllers'
VIRTUAL_PACKAGE_LENGTH = 4

# define the local filepath to the apps dir
ETC_PATH = get_apps_dir()

# define path segment within an apps dir
CONTROLLER_SUBPATH = os.path.join('appserver', 'controllers')


class ControllerMetaLoader(object):
    '''
    Unified import hook handler.  Implements base methods to support dynamic
    module importing via the meta hooks method.
    '''

    __qualified_apps = []


    @classmethod
    def crawl_apps(cls):
        '''
        Generates the list of apps that appear to have the correct directory
        structure for housing custom endpoints.
        '''

        # Read the flag directly from disk so it works at startup before
        # splunkd authentication is available. getMergedConf reads via
        # btool using the pre-cached merged file generated by the launcher.
        _disable_controllers = False
        try:
            from splunk.util import normalizeBoolean
            conf = getMergedConf('web-features')
            value = conf.get('feature:appserver_security', {}).get(
                'deactivate_custom_cherrypy_controllers', False)
            _disable_controllers = normalizeBoolean(value)
        except Exception as e:
            logger.warning("APPSERVER_SECURITY_FRAMEWORK - crawl_apps: failed to read flag, defaulting to False: %s", e)
        cls.__qualified_apps = []
        for path in os.listdir(ETC_PATH):
            eligible_dir = os.path.join(ETC_PATH, path, CONTROLLER_SUBPATH)
            if os.path.isdir(eligible_dir):
                if _disable_controllers:
                    logger.warning("APPSERVER_SECURITY_FRAMEWORK - Blocked controller discovery: app=%s", path)
                else:
                    logger.warning("APPSERVER_SECURITY_FRAMEWORK - DEPRECATION - Custom app CherryPy controller registered. This feature is deprecated and will be removed in a future release. Update this app to use supported Splunk Web extension points. app=%s", path)
                    cls.__qualified_apps.append(path)
        

    @classmethod
    def get_apps(self):
        '''
        Returns the list of eligible app names
        '''
        return ControllerMetaLoader.__qualified_apps


    @classmethod
    def get_registered_endpoints(cls, app):
        '''
        Returns a list of endpoints registered by app developer in web.conf
        '''

        listing = Popen(['btool', '--app=%s' % app, 'web', 'list'], stdout=PIPE, close_fds=True).communicate()[0]
        listing = listing.decode()

        lines = listing.split('\n')
        rex = re.compile(r'\s*\[endpoint:([A-Za-z0-9_]+)')
        output = []
        for line in lines:
            match = rex.search(line)
            if match:
                output.append(match.group(1))
        return output


    def find_spec(self, fullname, path, target=None):
        # Only handle our virtual package and its children
        if not fullname.startswith(VIRTUAL_PACKAGE_NAME):
            return None
        relative_name = fullname.replace(VIRTUAL_PACKAGE_NAME, '').strip('.')
        relative_parts = relative_name.split('.') if relative_name else []
        if not relative_parts or len(relative_parts) < 1:
            # Virtual package itself
            return importlib.util.spec_from_loader(fullname, self, is_package=True)
        namespace = relative_parts[0]
        if namespace not in self.get_apps():
            return None
        if len(relative_parts) < 2:
            # App package
            return importlib.util.spec_from_loader(fullname, self, is_package=True)
        # Endpoint module
        module_name = relative_parts[1]
        file_path = os.path.join(ETC_PATH, namespace, CONTROLLER_SUBPATH, module_name + '.py')
        if not os.path.isfile(file_path):
            return None
        return importlib.util.spec_from_loader(fullname, self, origin=file_path)


    def create_module(self, spec):
        # Use default module creation semantics
        return None

    def exec_module(self, module):
        fullname = module.__name__
        relative_name = fullname.replace(VIRTUAL_PACKAGE_NAME, '').strip('.')
        relative_parts = relative_name.split('.') if relative_name else []
        if not relative_parts or len(relative_parts) < 1:
            # Virtual package itself
            module.__file__ = '<virtual package: %s>' % VIRTUAL_PACKAGE_NAME
            module.__loader__ = self
            module.__path__ = []
            return
        namespace = relative_parts[0]
        if len(relative_parts) < 2:
            # App package
            module.__file__ = '<virtual package: %s>' % (VIRTUAL_PACKAGE_NAME + '.' + '.'.join(relative_parts))
            module.__loader__ = self
            module.__path__ = []
            logger.debug('LOAD: returning wrapper package: %s' % module.__file__)
            return
        # Endpoint module
        module_name = relative_parts[1]
        file_path = os.path.join(ETC_PATH, namespace, CONTROLLER_SUBPATH, module_name + '.py')
        logger.debug('LOAD: reading file: %s' % file_path)
        try:
            with open(file_path, 'r') as f:
                code = f.read()
        except Exception as e:
            logger.debug(e)
            raise ImportError(f"Could not read {file_path}: {e}")
        if not code:
            raise ImportError(f"No code in {file_path}")
        try:
            codeobj = compile(code, file_path, "exec")
        except SyntaxError as e:
            logger.error(f"{file_path} contains Python syntax errors: {e}")
            raise
        try:
            exec(codeobj, module.__dict__)
        except Exception as e:
            logger.error(f"{file_path} cannot be executed by Python: {e}")
            raise



class CustomController(controllers.BaseController):
    """
    handle custom controllers
    """
    def _cp_dispatch(self, vpath):
        from splunk.WebFeatures import WebFeaturesSingleton
        if WebFeaturesSingleton().get_bool_setting(
                'feature:appserver_security', 'deactivate_custom_cherrypy_controllers'):
            logger.warning("APPSERVER_SECURITY_FRAMEWORK - Blocked custom controller request: path=%s", '/'.join(vpath))
            raise cherrypy.HTTPError(404)
        if len(vpath) > 1:
            app = vpath.pop(0)
            logger.debug('return custom controller for %s ' % app)
            controller = self._custom_controllers[app]
            logger.warning("APPSERVER_SECURITY_FRAMEWORK - DEPRECATION - Custom app CherryPy controller invoked. This feature is deprecated and will be removed in a future release. Update this app to use supported Splunk Web extension points. app=%s, path=%s", app, '/'.join(vpath))
            return controller
        return vpath

    def load_handlers(self):
        self._custom_controllers = dict()
        for app in ControllerMetaLoader.get_apps():

            # first add an app controller here
            self._custom_controllers[app] = controllers.BaseController()
            
            for endpoint in ControllerMetaLoader.get_registered_endpoints(app):

                # import the module
                try:
                    full_module = '.'.join([VIRTUAL_PACKAGE_NAME, app, endpoint])
                    __import__(full_module)
                    mod = sys.modules[full_module]
                except Exception as e:
                    logger.error('cannot load specified module %s in app %s: %s' % (endpoint, app, e))
                    if logger.isEnabledFor(logging.DEBUG):
                        logger.exception(e)
                    continue
                
                # find the first BaseController sub-class in the module and
                # attach it
                for prop in mod.__dict__:
                    try:
                        if inspect.isclass(mod.__dict__[prop]) and \
                                issubclass(mod.__dict__[prop], controllers.BaseController):
                            setattr(self._custom_controllers[app], endpoint, mod.__dict__[prop]())
                            logger.info('Registering custom app endpoint: %s/%s' % (app, endpoint))
                            break 
                    except Exception as e:
                        logger.exception(e)



# init meta loader and read in apps
sys.meta_path.append(ControllerMetaLoader())
ControllerMetaLoader.crawl_apps()
